#================================================================================================================================================================
# Database creation
#================================================================================================================================================================
CREATE DATABASE Medicare;
USE Medicare;

#==================================================================================================================================================================
# Table creation and insertion of values
#==================================================================================================================================================================
CREATE TABLE Hospitals(
hospital_id VARCHAR(6) NOT NULL,
hospital_name VARCHAR(100) NOT NULL,
hospital_type VARCHAR(40) NOT NULL,
city VARCHAR(50) NOT NULL,
state VARCHAR(50) NOT NULL,
region VARCHAR(20) NOT NULL,
bed_capacity INT NOT NULL,
established_year INT NOT NULL,
contact_number VARCHAR(20),
email VARCHAR(100),
CONSTRAINT pk_hospitals PRIMARY KEY(hospital_id)
);

CREATE TABLE Departments (
    department_id VARCHAR(10) NOT NULL,
    department_name VARCHAR(100) NOT NULL,
    hospital_id VARCHAR(10) NOT NULL,
    floor_number INT NOT NULL,
    head_doctor_id VARCHAR(10),
    
    PRIMARY KEY(department_id),
    
    CONSTRAINT fk_departments_hospital FOREIGN KEY(hospital_id) REFERENCES Hospitals(hospital_id)
    
);



CREATE TABLE Doctors (
    doctor_id VARCHAR(10) NOT NULL PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    gender VARCHAR(20) NOT NULL,
    specialization VARCHAR(100) NOT NULL,
    department_id VARCHAR(10),
    hospital_id VARCHAR(10) NOT NULL,
    qualification VARCHAR(100) NOT NULL,
    experience_years INT NOT NULL,
    consultation_fee DECIMAL(10,2) NOT NULL,
    phone_number VARCHAR(20) NOT NULL,
    email VARCHAR(150),
    joining_date VARCHAR(20) NOT NULL,
    
    CONSTRAINT fk_Doctors_Department FOREIGN KEY(department_id) REFERENCES Departments(department_id),
    CONSTRAINT fk_Doctors_Hospital FOREIGN KEY(hospital_id) REFERENCES Hospitals(hospital_id)
);


CREATE TABLE Patients (
    patient_id VARCHAR(15) NOT NULL PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    gender VARCHAR(20) NOT NULL,
    date_of_birth DATE NOT NULL,
    age INT NOT NULL,
    city VARCHAR(100) NOT NULL,
    state VARCHAR(100) NOT NULL,
    phone_number VARCHAR(20) NOT NULL,
    email VARCHAR(150),
    blood_group VARCHAR(10) NOT NULL,
    registration_date DATE NOT NULL
);
